document.querySelector('#unsubscribe').addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{const response=await fetch('/api/unsubscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:new URLSearchParams(location.search).get('token')})});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.error||'Please try again.');document.querySelector('#message').textContent='You’re unsubscribed. You will not receive storybook launch emails.';button.hidden=true;history.replaceState(null,'','/unsubscribe');}catch(error){document.querySelector('#message').textContent=error.message;button.disabled=false;}});
